# owner: platform
import unittest

from rosterkit.notices import build_absence_notice
from rosterkit.models import Mark, Student
from datetime import date

STUDENT = Student("7", "Rivera", "Ana", "A")

# ---
def mark(day, status="absent", student_id="7"):
    return Mark(student_id, date(2026, 3, day), status)

class NoticeTests(unittest.TestCase):
    def test_names_student_count_and_sorted_dates(self):
        marks = [mark(9), mark(2), mark(5, "present")]
        text = build_absence_notice(STUDENT, marks)
        self.assertEqual(text, "Ana Rivera missed 2 days: 2026-03-02, 2026-03-09.")

    def test_single_day_is_singular(self):
        text = build_absence_notice(STUDENT, [mark(4)])
        self.assertEqual(text, "Ana Rivera missed 1 day: 2026-03-04.")

    def test_other_students_mark_is_rejected(self):
        with self.assertRaises(ValueError):
            build_absence_notice(STUDENT, [mark(4), mark(5, student_id="8")])

    def test_no_absences_is_rejected(self):
        with self.assertRaises(ValueError):
            build_absence_notice(STUDENT, [mark(4, "late")])

    def test_empty_marks_is_rejected(self):
        with self.assertRaises(ValueError):
            build_absence_notice(STUDENT, [])
